import{_ as a,o as e,c as r,ag as n}from"./chunks/framework.C9sp7nFj.js";const P=JSON.parse('{"title":"SetExternalTCP 设置外部工具坐标系","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/5. 设置指令/SetExternalTCP.md","filePath":"3. 指令/5. 设置指令/SetExternalTCP.md","lastUpdated":1778862643000}'),s={name:"3. 指令/5. 设置指令/SetExternalTCP.md"};function l(o,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="setexternaltcp-设置外部工具坐标系" tabindex="-1">SetExternalTCP 设置外部工具坐标系 <a class="header-anchor" href="#setexternaltcp-设置外部工具坐标系" aria-label="Permalink to &quot;SetExternalTCP 设置外部工具坐标系&quot;">​</a></h1><p>该指令用于<strong>设置并切换机器人的外部工具坐标系（Remote TCP）</strong>。与传统的 <code>SetTool</code>（工具安装在法兰上）不同，外部 TCP 模式通常用于机器人抓取工件在固定的外部工具（如固定的焊枪、打磨机或涂胶头）上运动的场景。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>SetExternalTCP(ExtTCP) SetExternalTCP(外部 TCP 参数)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>ExtTCP：外部 TCP 参数（ExternalTCP Param）</td><td>EXTTCP 变量</td><td>指定当前需要启用的外部工具坐标系。该数据定义了固定在外部的工具尖端相对于机器人基坐标系（Base）的位置和姿态。</td><td></td></tr></tbody></table><hr><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><p>当启用外部 TCP 时，机器人的运动控制逻辑会发生反转：系统会保证<strong>抓取的工件</strong>相对于<strong>固定在外部的工具点</strong>进行精确的轨迹运动（如圆弧或直线）。这对于需要高精度表面处理的工艺至关重要。</p><hr><h2 id="示例" tabindex="-1">示例： <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例：&quot;">​</a></h2><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetExternalTCP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(EXTTCP0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>执行结果：</strong></p><p>选择 <strong>EXTTCP0</strong> 作为机器人当前参考的外部工具坐标系参数。</p><hr><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>固定点涂胶</strong>：机器人抓取工件，绕着固定的点胶头旋转或平移。</li><li><strong>固定位打磨</strong>：机器人抓取零件，在固定的砂带机或抛光轮上按特定轨迹进行加工。</li><li><strong>外部视觉引导</strong>：当相机或激光传感器固定在工作台上方，需将工件送至其下方进行动态检测时。</li></ul>',18)])])}const T=a(s,[["render",l]]);export{P as __pageData,T as default};
